import React from 'react';

import PauseCircle from '@pohodnik/icons/svg/Media/PauseCircle';
import PlayCircle from '@pohodnik/icons/svg/Media/PlayCircle';

import { IWorkoutTrackMarkup } from '@apps/Workouts/@types/workoutTrackMarkup.types';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';

interface IWorkoutTrackMarkupItemProps {
  markup: IWorkoutTrackMarkup;
  onDelete?: (e: React.MouseEvent) => void;
  onEdit?: (e: React.MouseEvent) => void;
}

const WorkoutTrackMarkupItem: React.FC<IWorkoutTrackMarkupItemProps> = ({
  markup,
  onDelete,
  onEdit,
}) => {
  const title = [
    markup.name,
    markup.utcD1.toLocaleString(),
    markup.utcD2.toLocaleString(),
    `${Math.floor((markup.utcD2.getTime() - markup.utcD1.getTime()) / 60000)} мин.`,
    dateRangeToLocaleString(markup.utcD1, markup.utcD2),
  ].join('\n');
  return (
    <div className="m-n1 d-flex justify-content-between">
      <em title={title} className="flex-grow-1 text-truncate">
        {markup.isBreak ? <PauseCircle /> : <PlayCircle />}
        &nbsp;
        {markup.name}
      </em>

      <aside className="d-flex flex-nowrap align-items-start">
        {onEdit && <PohButton icon={IconsEnum.edit} onClick={onEdit} size={ButtonSize.Small} />}
        {onDelete && (
          <PohButton icon={IconsEnum.trash} onClick={onDelete} size={ButtonSize.Small} />
        )}
      </aside>
    </div>
  );
};

export default WorkoutTrackMarkupItem;
